  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the final booking price for this trip after evaluating membership discount eligibility.
   * Algorithm:
   * 1. If customer is null or bookingTime is null or this.price is invalid, return this.price.
   * 2. If customer does not have a membership package, return this.price.
   * 3. If the customer's membership package does not contain Award.DISCOUNTS, return this.price.
   * 4. Check whether bookingTime is at least 24 hours before this.trip's departure time.
   * 5. If the discount condition is satisfied, return this.price * 0.8 rounded to one decimal place.
   * 6. Otherwise, return this.price.
   * Related Features:
   * - price
   * - departureTime
   * Related Classes: Customer, MembershipPackage, Award
   * Input:
   * - customer : Customer
   *   - The customer making the booking.
   * - bookingTime : String
   *   - The booking timestamp used to evaluate the 24-hour discount rule.
   * Output:
   * - double
   * - The final price after applying the 20 percent discount when eligible; otherwise the original trip price.
   * - The returned amount keeps one decimal place.
   * Pre-condition:
   * - customer and bookingTime may be null; null values cause the original trip price to be returned.
   * Post-condition:
   * - No state changes.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null || Double.isNaN(price) || Double.isInfinite(price))
    {
      return price;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return price;
    }
    if (departureTime == null || departureTime.length() == 0)
    {
      return price;
    }
    try
    {
      java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ISO_LOCAL_DATE_TIME;
      java.time.LocalDateTime bookingDateTime = java.time.LocalDateTime.parse(bookingTime, formatter);
      java.time.LocalDateTime departureDateTime = java.time.LocalDateTime.parse(departureTime, formatter);
      java.time.Duration duration = java.time.Duration.between(bookingDateTime, departureDateTime);
      if (duration.toHours() >= 24)
      {
        return Math.round((price * 0.8) * 10.0) / 10.0;
      }
    }
    catch (Exception e)
    {
      return price;
    }
    return price;
    
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the reward points generated from bookings on this trip for a given customer and month.
   * Algorithm:
   * 1. If customer is null or currentMonth is null, return 0.
   * 2. If customer.membershipPackage is null or does not contain Award.POINTS, return 0.
   * 3. Iterate through this trip's bookings.
   * 4. Count only bookings that belong to the given customer and satisfy booking.isInMonth(currentMonth).
   * 5. Add 5 points per booked seat.
   * 6. Return the total points.
   * Related Features:
   * - bookings
   * - price
   * Related Classes: Booking, Customer, MembershipPackage, Award
   * Input:
   * - customer : Customer
   *   - The customer whose points are being calculated.
   * - currentMonth : String
   *   - Requested month in the system month format.
   * Output:
   * - int
   * - Total points earned for this trip's bookings by the customer in that month.
   * Pre-condition:
   * - currentMonth must be provided.
   * - customer may be null, which yields 0.
   * - Only customers with Award.POINTS are eligible.
   * Post-condition:
   * - No state changes.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
    {
      return 0;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.POINTS))
    {
      return 0;
    }
    int total = 0;
    if (bookings != null && !bookings.isEmpty())
    {
      for (Booking booking : bookings)
      {
        if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
        {
          total += booking.getNumberOfSeats() * 5;
        }
      }
    }
    return total;
    
  }

